schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/new-dependency-risk-checklist.json",
  "title": "New dependency risk record",
  "type": "object",
  "required": ["package", "owner", "inputs", "advisory_lookup", "lockfile", "decision", "evidence", "alert_routing", "review"],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "url": {"type": "string", "pattern": "^https://"},
    "window": {"type": "string", "pattern": "^[0-9]+d$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "package": {
      "type": "object",
      "required": ["name", "version", "ecosystem", "registry_repository_url", "readme_repository_url", "repository_matches", "near_name", "install_scripts"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "minLength": 1, "pattern": "^[^\\s]+$"},
        "version": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+(\\.[0-9]+)?([-+][0-9A-Za-z.-]+)?$"},
        "ecosystem": {"type": "string", "enum": ["npm", "pypi", "crates.io", "go", "maven", "rubygems", "nuget"]},
        "registry_repository_url": {"$ref": "#/definitions/url"},
        "readme_repository_url": {"$ref": "#/definitions/url"},
        "repository_matches": {"type": "boolean"},
        "near_name": {
          "type": "object",
          "required": ["searched", "popular_near_name"],
          "additionalProperties": false,
          "properties": {
            "searched": {"type": "boolean", "const": true},
            "popular_near_name": {"type": ["string", "null"]}
          }
        },
        "install_scripts": {
          "type": "object",
          "required": ["declared", "hooks"],
          "additionalProperties": false,
          "properties": {
            "declared": {"type": "boolean"},
            "hooks": {
              "type": "array",
              "items": {
                "type": "object",
                "required": ["hook", "runs"],
                "additionalProperties": false,
                "properties": {
                  "hook": {"type": "string", "enum": ["preinstall", "install", "postinstall"]},
                  "runs": {"type": "string", "minLength": 2}
                }
              }
            }
          },
          "if": {"properties": {"declared": {"const": true}}},
          "then": {"properties": {"hooks": {"minItems": 1}}}
        }
      }
    },
    "owner": {"$ref": "#/definitions/handle"},
    "inputs": {
      "type": "array",
      "minItems": 6,
      "allOf": [
        {"contains": {"properties": {"name": {"const": "licence"}}}},
        {"contains": {"properties": {"name": {"const": "transitive_count"}}}},
        {"contains": {"properties": {"name": {"const": "maintainers"}}}},
        {"contains": {"properties": {"name": {"const": "last_release"}}}},
        {"contains": {"properties": {"name": {"const": "alternative"}}}},
        {"contains": {"properties": {"name": {"const": "patch_window"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "value"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["licence", "transitive_count", "maintainers", "last_release", "alternative", "patch_window", "useful_surface_lines", "distribution_model"]},
          "value": {}
        },
        "allOf": [
          {"if": {"properties": {"name": {"const": "licence"}}},
           "then": {"properties": {"value": {"type": "string", "minLength": 3, "pattern": "^(?![Uu]nknown|[Ss]ee repo|MIT-ish)[A-Za-z0-9.+-]+( (WITH|OR|AND) [A-Za-z0-9.+-]+)*$"}}}},
          {"if": {"properties": {"name": {"const": "transitive_count"}}},
           "then": {"properties": {"value": {"type": "integer", "minimum": 0}}}},
          {"if": {"properties": {"name": {"const": "maintainers"}}},
           "then": {"properties": {"value": {"type": "integer", "minimum": 1}}}},
          {"if": {"properties": {"name": {"const": "last_release"}}},
           "then": {"properties": {"value": {"$ref": "#/definitions/date"}}}},
          {"if": {"properties": {"name": {"const": "alternative"}}},
           "then": {"properties": {"value": {
             "type": "array", "minItems": 1,
             "items": {
               "type": "object",
               "required": ["name", "reason"],
               "additionalProperties": false,
               "properties": {"name": {"type": "string", "minLength": 2}, "reason": {"type": "string", "minLength": 8}}
             },
             "contains": {"properties": {"name": {"enum": ["in-house", "already-in-tree"]}}}}}}},
          {"if": {"properties": {"name": {"const": "patch_window"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["critical", "high"],
             "additionalProperties": false,
             "properties": {"critical": {"$ref": "#/definitions/window"}, "high": {"$ref": "#/definitions/window"}}}}}},
          {"if": {"properties": {"name": {"const": "useful_surface_lines"}}},
           "then": {"properties": {"value": {"type": "integer", "minimum": 1}}}},
          {"if": {"properties": {"name": {"const": "distribution_model"}}},
           "then": {"properties": {"value": {"type": "string", "enum": ["saas-backend", "shipped-binary", "browser-bundle", "internal-tool"]}}}}
        ]
      }
    },
    "advisory_lookup": {
      "type": "object",
      "required": ["source", "url", "checked_on", "open_advisories"],
      "additionalProperties": false,
      "properties": {
        "source": {"type": "string", "enum": ["osv.dev", "github-advisory-database", "nvd"]},
        "url": {"$ref": "#/definitions/url"},
        "checked_on": {"$ref": "#/definitions/date"},
        "open_advisories": {"type": "array", "items": {"type": "string", "pattern": "^(CVE-[0-9]{4}-[0-9]{4,}|GHSA-[0-9a-z]{4}-[0-9a-z]{4}-[0-9a-z]{4})$"}}
      }
    },
    "lockfile": {
      "type": "object",
      "required": ["file", "commit_url"],
      "additionalProperties": false,
      "properties": {
        "file": {"type": "string", "enum": ["package-lock.json", "yarn.lock", "pnpm-lock.yaml", "poetry.lock", "uv.lock", "requirements.txt (hashed)", "Cargo.lock", "go.sum", "Gemfile.lock", "packages.lock.json"]},
        "commit_url": {"$ref": "#/definitions/url"}
      }
    },
    "decision": {
      "type": "object",
      "required": ["verdict", "statement"],
      "additionalProperties": false,
      "properties": {
        "verdict": {"type": "string", "enum": ["accept", "accept-with-mitigation", "reject", "in-house"]},
        "statement": {"type": "string", "minLength": 20, "pattern": "@[0-9]+\\.[0-9]+"},
        "fallback": {
          "type": "object",
          "required": ["kind", "target"],
          "additionalProperties": false,
          "properties": {
            "kind": {"type": "string", "enum": ["vendor", "fork", "alternative"]},
            "target": {"type": "string", "minLength": 2}
          }
        },
        "mitigation": {
          "type": "object",
          "required": ["advisory_id", "action"],
          "additionalProperties": false,
          "properties": {
            "advisory_id": {"type": "string", "pattern": "^(CVE-[0-9]{4}-[0-9]{4,}|GHSA-[0-9a-z]{4}-[0-9a-z]{4}-[0-9a-z]{4})$"},
            "action": {"type": "string", "minLength": 8}
          }
        },
        "distribution_model": {"type": "string", "enum": ["saas-backend", "shipped-binary", "browser-bundle", "internal-tool"]},
        "override_reason": {"type": "string", "minLength": 12},
        "install_hook_reason": {"type": "string", "minLength": 12}
      },
      "if": {"properties": {"verdict": {"const": "accept-with-mitigation"}}},
      "then": {"required": ["mitigation"]}
    },
    "evidence": {
      "type": "array",
      "minItems": 2,
      "items": {"$ref": "#/definitions/url"},
      "allOf": [
        {"contains": {"pattern": "osv\\.dev|github\\.com/advisories|nvd\\.nist\\.gov"}},
        {"contains": {"pattern": "/commit/|/pull/|/merge_requests/"}}
      ]
    },
    "alert_routing": {
      "type": "object",
      "required": ["tool", "recipient"],
      "additionalProperties": false,
      "properties": {
        "tool": {"type": "string", "enum": ["dependabot", "renovate", "npm-audit", "pip-audit", "cargo-audit", "govulncheck"]},
        "recipient": {"$ref": "#/definitions/handle"}
      }
    },
    "review": {
      "type": "object",
      "required": ["reopen_on", "next_review_at"],
      "additionalProperties": false,
      "properties": {
        "reopen_on": {"type": "string", "const": "major-version-bump"},
        "next_review_at": {"$ref": "#/definitions/date"}
      }
    }
  }
}

output-contract.example:
{
  "package": {
    "name": "dayjs",
    "version": "1.11.10",
    "ecosystem": "npm",
    "registry_repository_url": "https://github.com/iamkun/dayjs",
    "readme_repository_url": "https://github.com/iamkun/dayjs",
    "repository_matches": true,
    "near_name": {"searched": true, "popular_near_name": null},
    "install_scripts": {"declared": false, "hooks": []}
  },
  "owner": "swe:alice",
  "inputs": [
    {"name": "licence", "value": "MIT"},
    {"name": "transitive_count", "value": 0},
    {"name": "maintainers", "value": 3},
    {"name": "last_release", "value": "2026-07-18"},
    {"name": "alternative", "value": [
      {"name": "in-house", "reason": "locale tables and DST handling are far more than twenty lines"},
      {"name": "already-in-tree", "reason": "no date library in the lockfile; Intl.DateTimeFormat lacks parsing"},
      {"name": "date-fns", "reason": "tree-shakeable but 3x the bundle for the four functions we need"}
    ]},
    {"name": "patch_window", "value": {"critical": "7d", "high": "30d"}},
    {"name": "useful_surface_lines", "value": 400},
    {"name": "distribution_model", "value": "browser-bundle"}
  ],
  "advisory_lookup": {
    "source": "osv.dev",
    "url": "https://osv.dev/list?ecosystem=npm&q=dayjs%401.11.10",
    "checked_on": "2026-09-10",
    "open_advisories": []
  },
  "lockfile": {"file": "pnpm-lock.yaml", "commit_url": "https://github.com/acme/storefront/pull/2231/commits/9f3c1e2"},
  "decision": {
    "verdict": "accept",
    "statement": "Accept dayjs@1.11.10 as a direct dependency of the storefront browser bundle; MIT; no transitive additions; three maintainers with a release two months ago."
  },
  "evidence": [
    "https://osv.dev/list?ecosystem=npm&q=dayjs%401.11.10",
    "https://github.com/acme/storefront/pull/2231/commits/9f3c1e2",
    "https://www.npmjs.com/package/dayjs"
  ],
  "alert_routing": {"tool": "renovate", "recipient": "swe:alice"},
  "review": {"reopen_on": "major-version-bump", "next_review_at": "2027-03-10"}
}

{
  "package": {
    "name": "crossenv",
    "version": "^6.1.1",
    "ecosystem": "npm",
    "registry_repository_url": "https://github.com/kentcdodds/cross-env",
    "readme_repository_url": "https://github.com/kentcdodds/cross-env",
    "repository_matches": false,
    "near_name": {"searched": true, "popular_near_name": "cross-env"},
    "install_scripts": {"declared": true, "hooks": [{"hook": "postinstall", "runs": "node package-setup.js (posts process.env to a remote host)"}]}
  },
  "owner": "swe:bob",
  "inputs": [
    {"name": "licence", "value": "MIT-ish"},
    {"name": "transitive_count", "value": 0},
    {"name": "maintainers", "value": 1},
    {"name": "last_release", "value": "2024-06-01"},
    {"name": "alternative", "value": [
      {"name": "dotenv", "reason": "different purpose, does not set env for a child process"}
    ]},
    {"name": "patch_window", "value": {"critical": "7d", "high": "30d"}}
  ],
  "advisory_lookup": {
    "source": "osv.dev",
    "url": "https://osv.dev/list?ecosystem=npm&q=crossenv",
    "checked_on": "2026-09-10",
    "open_advisories": ["GHSA-6h6q-4wq8-7w5g"]
  },
  "lockfile": {"file": "package-lock.json", "commit_url": "https://github.com/acme/storefront/pull/2232"},
  "decision": {
    "verdict": "accept",
    "statement": "Accept crossenv for cross-platform env vars in npm scripts."
  },
  "evidence": [
    "https://osv.dev/list?ecosystem=npm&q=crossenv",
    "https://github.com/acme/storefront/pull/2232"
  ],
  "alert_routing": {"tool": "dependabot", "recipient": "team:platform"},
  "review": {"reopen_on": "major-version-bump", "next_review_at": "2027-03-10"}
}
